window.FACTS_DATA = [{"id":"cleopatra-moon-landing","subject":"Cleopatra","text":{"en":"Cleopatra lived closer in time to the Moon landing than to the construction of the Great Pyramid.","es":"Cleopatra vivió más cerca en el tiempo del alunizaje que de la construcción de la Gran Pirámide.","ca":"Cleopatra va viure més a prop en el temps de l'arribada a la Lluna que de la construcció de la Gran Piràmide."}},{"id":"honey-never-spoils","subject":"Honey","text":{"en":"Honey never spoils. Edible honey has been found in 3,000-year-old Egyptian tombs.","es":"La miel nunca se estropea. Se ha encontrado miel comestible en tumbas egipcias de 3000 años de antigüedad.","ca":"La mel mai es fa malbé. S'ha trobat mel comestible en tombes egípcies de 3.000 anys d'antiguitat."}},{"id":"flamingo-group-flamboyance","subject":"Flamingo","text":{"en":"A group of flamingos is called a flamboyance.","es":"En inglés, a un grupo de flamencos se le llama 'flamboyance' (algo así como 'extravagancia').","ca":"En anglès, a un grup de flamencs se l'anomena 'flamboyance' (una mena d'‘extravagància’)."}},{"id":"nintendo-founded-1889","subject":"Nintendo","text":{"en":"Nintendo was founded in 1889 as a playing card company.","es":"Nintendo fue fundada en 1889 como una empresa de naipes.","ca":"Nintendo va ser fundada el 1889 com una empresa de cartes de joc."}},{"id":"sharks-older-than-trees","subject":"Shark","text":{"en":"Sharks are older than trees. Sharks appeared around 450 million years ago; trees around 350 million years ago.","es":"Los tiburones son más antiguos que los árboles. Los tiburones aparecieron hace unos 450 millones de años; los árboles, hace unos 350 millones de años.","ca":"Els taurons són més antics que els arbres. Els taurons van aparèixer fa uns 450 milions d'anys; els arbres, fa uns 350 milions d'anys."}},{"id":"octopus-three-hearts","subject":"Octopus","text":{"en":"Octopuses have three hearts and blue blood.","es":"Los pulpos tienen tres corazones y sangre azul.","ca":"Els pops tenen tres cors i sang blava."}},{"id":"shortest-war-anglo-zanzibar","subject":"Anglo-Zanzibar War","text":{"en":"The shortest war in history lasted 38 minutes between Britain and Zanzibar in 1896.","es":"La guerra más corta de la historia duró 38 minutos, entre Gran Bretaña y Zanzíbar, en 1896.","ca":"La guerra més curta de la història va durar 38 minuts, entre la Gran Bretanya i Zanzíbar, el 1896."}},{"id":"bananas-are-berries","subject":"Banana","text":{"en":"Bananas are berries, but strawberries aren't.","es":"Los plátanos son bayas, pero las fresas no lo son.","ca":"Els plàtans són baies, però les maduixes no ho són."}},{"id":"venus-day-longer-than-year","subject":"Venus","text":{"en":"A day on Venus is longer than a year on Venus.","es":"Un día en Venus dura más que un año en Venus.","ca":"Un dia a Venus dura més que un any a Venus."}},{"id":"unicorn-national-animal-scotland","subject":"Unicorn","text":{"en":"The unicorn is the national animal of Scotland.","es":"El unicornio es el animal nacional de Escocia.","ca":"L'unicorn és l'animal nacional d'Escòcia."}},{"id":"oxford-older-than-aztec-empire","subject":"University of Oxford","text":{"en":"Oxford University is older than the Aztec Empire.","es":"La Universidad de Oxford es más antigua que el Imperio azteca.","ca":"La Universitat d'Oxford és més antiga que l'Imperi asteca."}},{"id":"chess-more-than-atoms","subject":"Chess","text":{"en":"There are more possible iterations of a game of chess than there are atoms in the known universe.","es":"Existen más partidas posibles de ajedrez que átomos en el universo conocido.","ca":"Hi ha més partides possibles d'escacs que àtoms a l'univers conegut."}},{"id":"carrots-originally-purple","subject":"Carrot","text":{"en":"Carrots were originally purple before the 17th century when Dutch growers cultivated orange carrots.","es":"Las zanahorias eran originalmente moradas antes del siglo XVII, cuando agricultores neerlandeses cultivaron zanahorias de color naranja.","ca":"Les pastanagues eren originàriament morades abans del segle XVII, quan pagesos neerlandesos van cultivar pastanagues de color taronja."}},{"id":"eiffel-tower-thermal-expansion","subject":"Eiffel Tower","text":{"en":"The Eiffel Tower can be 15 cm taller during the summer due to thermal expansion.","es":"La Torre Eiffel puede llegar a ser 15 cm más alta en verano debido a la dilatación térmica.","ca":"La Torre Eiffel pot arribar a ser 15 cm més alta a l'estiu a causa de la dilatació tèrmica."}},{"id":"spaghetti-single-strand-spaghetto","subject":"Spaghetti","text":{"en":"A single strand of spaghetti is called a spaghetto.","es":"Un solo fideo de espagueti se llama 'spaghetto'.","ca":"Un sol fideu d'espaguetis s'anomena 'spaghetto'."}},{"id":"hashtag-octothorpe","subject":"Number sign","text":{"en":"The hashtag symbol is technically called an octothorpe.","es":"El símbolo de la almohadilla (#) se llama técnicamente octotorpe.","ca":"El símbol de la coixinet (#) s'anomena tècnicament octotorpe."}},{"id":"cows-best-friends","subject":"Cattle","text":{"en":"Cows have best friends and get stressed when they are separated.","es":"Las vacas tienen mejores amigas y se estresan cuando las separan de ellas.","ca":"Les vaques tenen millors amigues i s'estressen quan les separen d'elles."}},{"id":"koala-fingerprints-human-like","subject":"Koala","text":{"en":"The fingerprints of koalas are so similar to humans that they have been confused at crime scenes.","es":"Las huellas dactilares de los koalas son tan parecidas a las humanas que se han llegado a confundir en escenas del crimen.","ca":"Les empremtes dactilars dels coales són tan semblants a les humanes que s'han arribat a confondre en escenes del crim."}},{"id":"owls-group-parliament","subject":"Owl","text":{"en":"A group of owls is called a parliament.","es":"En inglés, a un grupo de búhos se le llama 'parliament' (parlamento).","ca":"En anglès, a un grup de mussols se l'anomena 'parliament' (parlament)."}},{"id":"pringles-inventor-buried-in-can","subject":"Fredric Baur","text":{"en":"The inventor of the Pringles can is now buried in one.","es":"El inventor del bote de Pringles está enterrado dentro de uno.","ca":"L'inventor del pot de Pringles està enterrat dins d'un."}},{"id":"sea-otters-hold-hands","subject":"Sea otter","text":{"en":"Sea otters hold hands when they sleep to keep from drifting apart.","es":"Las nutrias marinas se agarran de las patas mientras duermen para no separarse flotando.","ca":"Les llúdrigues marines s'agafen de les potes mentre dormen per no separar-se surant."}},{"id":"longest-word-without-vowel-rhythms","subject":"Rhythm","text":{"en":"The longest English word without a vowel is rhythms.","es":"La palabra inglesa más larga sin vocales es 'rhythms' (ritmos).","ca":"La paraula anglesa més llarga sense vocals és 'rhythms' (ritmes)."}},{"id":"ostrich-eye-bigger-than-brain","subject":"Ostrich","text":{"en":"An ostrich's eye is bigger than its brain.","es":"El ojo de un avestruz es más grande que su cerebro.","ca":"L'ull d'un estruç és més gran que el seu cervell."}},{"id":"wombat-cube-shaped-poop","subject":"Wombat","text":{"en":"Wombat poop is cube-shaped.","es":"Las heces del wombat tienen forma de cubo.","ca":"Els excrements del wombat tenen forma de cub."}},{"id":"frisbee-inventor-ashes-into-discs","subject":"Ed Headrick","text":{"en":"The inventor of the frisbee was turned into a frisbee after he died, with his ashes being molded into discs.","es":"El inventor del frisbee se convirtió en un frisbee después de morir: sus cenizas fueron moldeadas en discos.","ca":"L'inventor del frisbee es va convertir en un frisbee després de morir: les seves cendres van ser motllurades en discos."}},{"id":"pigeons-do-math-like-monkeys","subject":"Pigeon","text":{"en":"Pigeons can do math as well as monkeys.","es":"Las palomas pueden hacer cálculos matemáticos tan bien como los monos.","ca":"Els coloms poden fer càlculs matemàtics tan bé com els micos."}},{"id":"jiffy-unit-of-time","subject":"Jiffy (time)","text":{"en":"A jiffy is an actual unit of time: 1/100th of a second.","es":"Un 'jiffy' es una unidad de tiempo real: una centésima de segundo.","ca":"Un 'jiffy' és una unitat de temps real: una centèsima de segon."}},{"id":"dot-over-i-tittle","subject":"Tittle","text":{"en":"The dot over the letter 'i' is called a tittle.","es":"El punto sobre la letra 'i' se llama 'tittle'.","ca":"El punt sobre la lletra 'i' s'anomena 'tittle'."}},{"id":"maine-closest-state-to-africa","subject":"Maine","text":{"en":"Maine is the closest U.S. state to Africa.","es":"Maine es el estado de EE. UU. más cercano a África.","ca":"Maine és l'estat dels EUA més proper a l'Àfrica."}},{"id":"mickey-minnie-voice-actors-married","subject":"Wayne Allwine","text":{"en":"The voice actors for Mickey and Minnie Mouse were married in real life.","es":"Los actores que ponían voz a Mickey y Minnie Mouse, Wayne Allwine y Russi Taylor, estaban casados en la vida real.","ca":"Els actors que posaven veu a Mickey i Minnie Mouse, Wayne Allwine i Russi Taylor, estaven casats a la vida real."}},{"id":"switzerland-guinea-pig-law","subject":"Guinea pig","text":{"en":"In Switzerland, it is illegal to own just one guinea pig because they get lonely.","es":"En Suiza es ilegal tener un solo conejillo de Indias, porque se sienten solos.","ca":"A Suïssa és il·legal tenir un sol conillet d'Índies, perquè se senten sols."}},{"id":"woolly-mammoth-existed-during-pyramid","subject":"Woolly mammoth","text":{"en":"The woolly mammoth was still around when the Great Pyramid was being built.","es":"El mamut lanudo todavía existía cuando se estaba construyendo la Gran Pirámide.","ca":"El mamut llanut encara existia quan s'estava construint la Gran Piràmide."}},{"id":"more-stars-than-grains-of-sand","subject":"Star","text":{"en":"There are more stars in space than grains of sand on every beach on Earth.","es":"Hay más estrellas en el espacio que granos de arena en todas las playas de la Tierra.","ca":"Hi ha més estrelles a l'espai que grans de sorra a totes les platges de la Terra."}},{"id":"pugs-group-grumble","subject":"Pug","text":{"en":"A group of pugs is called a grumble.","es":"En inglés, a un grupo de carlinos (pugs) se le llama 'grumble' (algo así como 'refunfuño').","ca":"En anglès, a un grup de pugs se l'anomena 'grumble' (una mena de ‘rondinaire’)."}},{"id":"king-of-hearts-no-mustache","subject":"Playing card","text":{"en":"The King of Hearts is the only king in a deck of cards without a mustache.","es":"El Rey de Corazones es el único rey de la baraja sin bigote.","ca":"El Rei de Cors és l'únic rei de la baralla sense bigoti."}},{"id":"armadillos-can-get-leprosy","subject":"Armadillo","text":{"en":"Armadillos are the only animals besides humans that can contract leprosy.","es":"Los armadillos son los únicos animales, además de los humanos, que pueden contraer la lepra.","ca":"Els armadillos són els únics animals, a banda dels humans, que poden contraure la lepra."}},{"id":"crocodile-cannot-stick-out-tongue","subject":"Crocodile","text":{"en":"A crocodile cannot stick its tongue out.","es":"Un cocodrilo no puede sacar la lengua.","ca":"Un cocodril no pot treure la llengua."}},{"id":"alaska-north-west-east-state","subject":"Alaska","text":{"en":"Alaska is simultaneously the most northern, western, and eastern state in the U.S.","es":"Alaska es, al mismo tiempo, el estado más septentrional, más occidental y más oriental de EE. UU.","ca":"Alaska és, alhora, l'estat més septentrional, més occidental i més oriental dels EUA."}},{"id":"lighter-invented-before-match","subject":"Lighter","text":{"en":"The lighter was invented before the match.","es":"El encendedor se inventó antes que la cerilla.","ca":"L'encenedor es va inventar abans que el llumí."}},{"id":"lightning-bolt-toast-bread","subject":"Lightning","text":{"en":"A bolt of lightning contains enough energy to toast 100,000 slices of bread.","es":"Un rayo contiene energía suficiente para tostar 100.000 rebanadas de pan.","ca":"Un llamp conté prou energia per torrar 100.000 llesques de pa."}},{"id":"dolphins-have-names","subject":"Dolphin","text":{"en":"Dolphins have names for each other and can call out to specific individuals.","es":"Los delfines se ponen nombres entre ellos y pueden llamar a individuos concretos.","ca":"Els dofins es posen noms entre ells i poden cridar individus concrets."}},{"id":"oldest-recipe-is-beer","subject":"Beer","text":{"en":"The world's oldest known recipe is for beer.","es":"La receta más antigua conocida del mundo es la de la cerveza.","ca":"La recepta més antiga coneguda del món és la de la cervesa."}},{"id":"blue-whale-heart-human-swim","subject":"Blue whale","text":{"en":"A blue whale's heart is so large that a human could swim through its arteries.","es":"El corazón de una ballena azul es tan grande que una persona podría nadar por sus arterias.","ca":"El cor d'una balena blava és tan gran que una persona hi podria nedar per les artèries."}},{"id":"average-person-walks-three-times-around-world","subject":"Walking","text":{"en":"The average person walks the equivalent of three times around the world in their lifetime.","es":"Una persona promedio camina, a lo largo de su vida, el equivalente a dar tres vueltas al mundo.","ca":"Una persona mitjana camina, al llarg de la seva vida, l'equivalent a fer tres voltes al món."}},{"id":"bees-recognize-human-faces","subject":"Bee","text":{"en":"Bees can recognize human faces.","es":"Las abejas pueden reconocer rostros humanos.","ca":"Les abelles poden reconèixer cares humanes."}},{"id":"longest-hiccups-68-years","subject":"Charles Osborne (hiccups)","text":{"en":"The longest hiccupping spree lasted 68 years.","es":"El hipo más largo jamás registrado duró 68 años.","ca":"El singlot més llarg mai registrat va durar 68 anys."}},{"id":"earths-core-gold-coat-surface","subject":"Gold","text":{"en":"There is enough gold in Earth's core to coat the entire surface in 1.5 feet of gold.","es":"Hay suficiente oro en el núcleo de la Tierra para cubrir toda su superficie con una capa de 1,5 pies (unos 45 cm) de oro.","ca":"Hi ha prou or al nucli de la Terra per cobrir tota la seva superfície amb una capa d'1,5 peus (uns 45 cm) d'or."}},{"id":"snail-sleep-three-years","subject":"Snail","text":{"en":"A snail can sleep for three years.","es":"Un caracol puede dormir hasta tres años seguidos.","ca":"Un cargol pot dormir fins a tres anys seguits."}},{"id":"shuffled-deck-unique-sequence","subject":"Playing card","text":{"en":"The probability of shuffling a deck of cards into a sequence that has never existed is essentially 100%.","es":"La probabilidad de barajar una baraja de cartas en un orden que nunca haya existido antes es prácticamente del 100%.","ca":"La probabilitat de barrejar una baralla de cartes en un ordre que mai hagi existit abans és pràcticament del 100%."}},{"id":"mpemba-effect-hot-water-freezes-faster","subject":"Mpemba effect","text":{"en":"Hot water freezes faster than cold water under certain conditions, known as the Mpemba effect.","es":"El agua caliente puede congelarse más rápido que el agua fría en ciertas condiciones, un fenómeno conocido como el efecto Mpemba.","ca":"L'aigua calenta pot congelar-se més ràpid que l'aigua freda en certes condicions, un fenomen conegut com l'efecte Mpemba."}},{"id":"sloths-hold-breath-longer-than-dolphins","subject":"Sloth","text":{"en":"Sloths can hold their breath longer than dolphins can.","es":"Los perezosos pueden aguantar la respiración más tiempo que los delfines.","ca":"Els peresosos poden aguantar la respiració més temps que els dofins."}},{"id":"hawaiian-alphabet-12-letters","subject":"Hawaiian alphabet","text":{"en":"The Hawaiian alphabet only has 12 letters.","es":"El alfabeto hawaiano solo tiene 12 letras.","ca":"L'alfabet hawaià només té 12 lletres."}},{"id":"shrimp-heart-in-head","subject":"Shrimp","text":{"en":"A shrimp's heart is located in its head.","es":"El corazón de un camarón se encuentra en su cabeza.","ca":"El cor d'una gamba es troba al cap."}},{"id":"dead-people-goosebumps","subject":"Goose bumps","text":{"en":"Dead people can get goosebumps.","es":"Las personas fallecidas pueden tener piel de gallina.","ca":"Les persones mortes poden tenir pell de gallina."}},{"id":"twitter-bird-name-larry","subject":"Twitter","text":{"en":"The Twitter bird's official name is Larry.","es":"El nombre oficial del pájaro de Twitter es Larry.","ca":"El nom oficial de l'ocell de Twitter és Larry."}},{"id":"cloud-weighs-over-million-pounds","subject":"Cloud","text":{"en":"A single cloud can weigh more than 1 million pounds.","es":"Una sola nube puede pesar más de 1 millón de libras (unas 450 toneladas).","ca":"Un sol núvol pot pesar més d'1 milió de lliures (unes 450 tones)."}},{"id":"human-nose-trillion-scents","subject":"Nose","text":{"en":"The human nose can detect over 1 trillion different scents.","es":"La nariz humana puede detectar más de un billón de olores diferentes.","ca":"El nas humà pot detectar més d'un bilió d'olors diferents."}},{"id":"butterflies-taste-with-feet","subject":"Butterfly","text":{"en":"Butterflies taste with their feet.","es":"Las mariposas saborean con las patas.","ca":"Les papallones tasten amb les potes."}},{"id":"average-person-6-months-waiting-red-lights","subject":"Traffic light","text":{"en":"The average person spends 6 months of their lifetime waiting for red lights to turn green.","es":"Una persona promedio pasa 6 meses de su vida esperando a que los semáforos se pongan en verde.","ca":"Una persona mitjana passa 6 mesos de la seva vida esperant que els semàfors es posin verds."}},{"id":"crows-group-murder","subject":"Crow","text":{"en":"A group of crows is called a murder.","es":"En inglés, a un grupo de cuervos se le llama 'murder' (asesinato).","ca":"En anglès, a un grup de corbs se l'anomena 'murder' (assassinat)."}},{"id":"polar-bears-black-skin","subject":"Polar bear","text":{"en":"Polar bears have black skin under their white fur.","es":"Los osos polares tienen la piel negra bajo su pelaje blanco.","ca":"Els óssos polars tenen la pell negra sota el seu pelatge blanc."}},{"id":"great-wall-not-visible-from-space","subject":"Great Wall of China","text":{"en":"The Great Wall of China is not visible from space with the naked eye.","es":"La Gran Muralla China no es visible desde el espacio a simple vista.","ca":"La Gran Muralla Xinesa no és visible des de l'espai a simple vista."}},{"id":"cats-fewer-toes-back-paws","subject":"Cat","text":{"en":"Cats have fewer toes on their back paws than their front paws.","es":"Los gatos tienen menos dedos en las patas traseras que en las delanteras.","ca":"Els gats tenen menys dits a les potes del darrere que a les del davant."}},{"id":"longest-wedding-veil-63-football-fields","subject":"Veil","text":{"en":"The longest wedding veil was longer than 63 football fields.","es":"El velo de novia más largo del mundo medía más de 63 campos de fútbol.","ca":"El vel de núvia més llarg del món feia més de 63 camps de futbol."}},{"id":"cannot-hum-holding-nose","subject":"Humming","text":{"en":"You can't hum while holding your nose closed.","es":"No se puede tararear mientras te tapas la nariz.","ca":"No es pot taral·lejar mentre et tapes el nas."}},{"id":"jellyfish-group-smack","subject":"Jellyfish","text":{"en":"A group of jellyfish is called a smack.","es":"En inglés, a un grupo de medusas se le llama 'smack' (golpe).","ca":"En anglès, a un grup de meduses se l'anomena 'smack' (cop)."}},{"id":"average-cloud-weighs-1-1-million-pounds","subject":"Cloud","text":{"en":"The average cloud weighs about 1.1 million pounds.","es":"Una nube promedio pesa alrededor de 1,1 millones de libras (unas 500 toneladas).","ca":"Un núvol mitjà pesa al voltant d'1,1 milions de lliures (unes 500 tones)."}},{"id":"rats-laugh-when-tickled","subject":"Rat","text":{"en":"Rats laugh when they are tickled.","es":"Las ratas se ríen cuando les hacen cosquillas.","ca":"Les rates riuen quan els fan pessigolles."}},{"id":"average-person-25-years-asleep","subject":"Sleep","text":{"en":"The average person will spend 25 years asleep in their lifetime.","es":"Una persona promedio pasará 25 años de su vida durmiendo.","ca":"Una persona mitjana passarà 25 anys de la seva vida dormint."}},{"id":"mcdonalds-75-burgers-per-second","subject":"McDonald's","text":{"en":"McDonald's sells 75 hamburgers every second of every day.","es":"McDonald's vende 75 hamburguesas cada segundo, todos los días.","ca":"McDonald's ven 75 hamburgueses cada segon, tots els dies."}},{"id":"ferrets-group-business","subject":"Ferret","text":{"en":"A group of ferrets is called a business.","es":"En inglés, a un grupo de hurones se le llama 'business' (negocio).","ca":"En anglès, a un grup de fures se l'anomena 'business' (negoci)."}},{"id":"human-body-fat-seven-bars-soap","subject":"Adipose tissue","text":{"en":"The human body contains enough fat to make seven bars of soap.","es":"El cuerpo humano contiene suficiente grasa para fabricar siete pastillas de jabón.","ca":"El cos humà conté prou greix per fabricar set pastilles de sabó."}},{"id":"rhinos-group-crash","subject":"Rhinoceros","text":{"en":"A group of rhinoceroses is called a crash.","es":"En inglés, a un grupo de rinocerontes se le llama 'crash' (choque).","ca":"En anglès, a un grup de rinoceronts se l'anomena 'crash' (xoc)."}},{"id":"tigers-striped-skin","subject":"Tiger","text":{"en":"Tigers have striped skin, not just striped fur.","es":"Los tigres tienen la piel rayada, no solo el pelaje.","ca":"Els tigres tenen la pell ratllada, no només el pelatge."}},{"id":"pearls-melt-in-vinegar","subject":"Pearl","text":{"en":"Pearls melt in vinegar.","es":"Las perlas se disuelven en vinagre.","ca":"Les perles es dissolen en vinagre."}},{"id":"nerd-word-coined-dr-seuss","subject":"If I Ran the Zoo","text":{"en":"The word 'nerd' was first coined by Dr. Seuss in 'If I Ran the Zoo'.","es":"La palabra 'nerd' fue acuñada por primera vez por el Dr. Seuss en su libro 'If I Ran the Zoo'.","ca":"La paraula 'nerd' va ser encunyada per primera vegada pel Dr. Seuss al seu llibre 'If I Ran the Zoo'."}},{"id":"zebras-group-dazzle","subject":"Zebra","text":{"en":"A group of zebras is called a dazzle.","es":"En inglés, a un grupo de cebras se le llama 'dazzle' (deslumbramiento).","ca":"En anglès, a un grup de zebres se l'anomena 'dazzle' (enlluernament)."}},{"id":"apples-wake-you-up-more-than-coffee","subject":"Apple","text":{"en":"Apples are more effective at waking you up in the morning than coffee.","es":"Las manzanas son más eficaces para despertarte por la mañana que el café.","ca":"Les pomes són més eficaces per despertar-te al matí que el cafè."}},{"id":"moon-has-moonquakes","subject":"Moonquake","text":{"en":"The moon has moonquakes.","es":"La Luna tiene terremotos lunares, llamados 'moonquakes'.","ca":"La Lluna té terratrèmols lunars, anomenats 'moonquakes'."}},{"id":"parrots-group-pandemonium","subject":"Parrot","text":{"en":"A group of parrots is called a pandemonium.","es":"En inglés, a un grupo de loros se le llama 'pandemonium' (pandemonio).","ca":"En anglès, a un grup de lloros se l'anomena 'pandemonium' (pandemoni)."}},{"id":"babies-94-more-bones-than-adults","subject":"Human skeleton","text":{"en":"Babies have 94 more bones than adults.","es":"Los bebés tienen 94 huesos más que los adultos.","ca":"Els nadons tenen 94 ossos més que els adults."}},{"id":"tooth-only-part-cannot-heal","subject":"Tooth","text":{"en":"The tooth is the only part of the human body that cannot heal itself.","es":"El diente es la única parte del cuerpo humano que no puede curarse a sí misma.","ca":"La dent és l'única part del cos humà que no es pot curar a si mateixa."}},{"id":"cockroach-survive-without-head","subject":"Cockroach","text":{"en":"A cockroach can live for several weeks without its head.","es":"Una cucaracha puede vivir varias semanas sin cabeza.","ca":"Una panerola pot viure diverses setmanes sense cap."}},{"id":"scotland-421-words-for-snow","subject":"Scotland","text":{"en":"Scotland has 421 words for snow.","es":"Escocia tiene 421 palabras para referirse a la nieve.","ca":"Escòcia té 421 paraules per referir-se a la neu."}},{"id":"peanuts-are-legumes","subject":"Peanut","text":{"en":"Peanuts are not nuts; they are legumes.","es":"Los cacahuetes no son frutos secos; son legumbres.","ca":"Els cacauets no són fruits secs; són llegums."}},{"id":"hippo-group-bloat","subject":"Hippopotamus","text":{"en":"A group of hippos is called a bloat.","es":"En inglés, a un grupo de hipopótamos se le llama «bloat».","ca":"En anglès, a un grup d'hipopòtams se l'anomena «bloat»."}},{"id":"shortest-english-sentence","subject":"English language","text":{"en":"The shortest complete sentence in English is 'I am.'","es":"La oración completa más corta en inglés es «I am» (‘yo soy’).","ca":"La frase completa més curta en anglès és «I am» («jo sóc»)."}},{"id":"lark-group-exaltation","subject":"Lark","text":{"en":"A group of larks is called an exaltation.","es":"En inglés, a un grupo de alondras se le llama «exaltation» (‘exaltación’).","ca":"En anglès, a un grup d'aloses se l'anomena «exaltation» («exaltació»)."}},{"id":"venus-spins-clockwise","subject":"Venus","text":{"en":"Venus is the only planet that spins clockwise.","es":"Venus es el único planeta que gira en sentido horario.","ca":"Venus és l'únic planeta que gira en sentit horari."}},{"id":"microwave-invention-melted-chocolate","subject":"Percy Spencer","text":{"en":"The microwave was invented after a researcher walked by a radar tube and a chocolate bar melted in his pocket.","es":"El microondas se inventó después de que a un investigador se le derritiera una chocolatina en el bolsillo al pasar cerca de un tubo de radar.","ca":"El microones es va inventar després que a un investigador se li fongués una xocolatina a la butxaca en passar a prop d'un tub de radar."}},{"id":"duck-quack-no-echo","subject":"Duck","text":{"en":"A duck's quack doesn't echo, and no one knows why.","es":"El graznido de un pato no produce eco, y nadie sabe por qué.","ca":"El grall d'un ànec no fa eco, i ningú no sap per què."}},{"id":"first-oranges-were-green","subject":"Orange (fruit)","text":{"en":"The first oranges weren't orange; they were green.","es":"Las primeras naranjas no eran de color naranja; eran verdes.","ca":"Les primeres taronges no eren de color taronja; eren verdes."}},{"id":"horses-cannot-vomit","subject":"Horse","text":{"en":"Horses cannot vomit or breathe through their mouths.","es":"Los caballos no pueden vomitar ni respirar por la boca.","ca":"Els cavalls no poden vomitar ni respirar per la boca."}},{"id":"raven-group-unkindness","subject":"Common raven","text":{"en":"A group of ravens is called an unkindness.","es":"En inglés, a un grupo de cuervos se le llama «unkindness» (‘falta de amabilidad’).","ca":"En anglès, a un grup de corbs se l'anomena «unkindness» («manca d'amabilitat»)."}},{"id":"longest-time-between-twins-born","subject":"Twin","text":{"en":"The longest time between two twins being born is 87 days.","es":"El mayor intervalo registrado entre el nacimiento de dos gemelos es de 87 días.","ca":"El major interval registrat entre el naixement de dos bessons és de 87 dies."}},{"id":"human-half-hour-single-cell","subject":"Zygote","text":{"en":"Every human spent about half an hour as a single cell.","es":"Todo ser humano pasó unos treinta minutos siendo una sola célula.","ca":"Tot ésser humà va passar uns trenta minuts sent una única cèl·lula."}},{"id":"toothpaste-blob-nurdle","subject":"Toothpaste","text":{"en":"The blob of toothpaste on a toothbrush is called a nurdle.","es":"La porción de pasta de dientes que se pone en el cepillo se llama «nurdle».","ca":"La porció de pasta de dents que es posa al raspall s'anomena «nurdle»."}},{"id":"cows-kill-more-than-sharks","subject":"Cattle","text":{"en":"Cows kill more people than sharks do every year.","es":"Las vacas matan a más personas cada año que los tiburones.","ca":"Les vaques maten més persones cada any que els taurons."}},{"id":"taser-name-tom-swift","subject":"Taser","text":{"en":"The inventor of the Taser named it after a book series: Tom Swift and His Electric Rifle.","es":"El inventor de la pistola Taser le puso ese nombre en honor a una serie de libros: Tom Swift and His Electric Rifle.","ca":"L'inventor de la pistola Taser li va posar aquest nom en honor a una sèrie de llibres: Tom Swift and His Electric Rifle."}},{"id":"porcupine-group-prickle","subject":"Porcupine","text":{"en":"A group of porcupines is called a prickle.","es":"En inglés, a un grupo de puercoespines se le llama «prickle» (‘pincho’).","ca":"En anglès, a un grup de porcs espins se l'anomena «prickle» («punxa»)."}},{"id":"strawberries-more-vitamin-c-than-oranges","subject":"Strawberry","text":{"en":"Strawberries have more vitamin C than oranges.","es":"Las fresas tienen más vitamina C que las naranjas.","ca":"Les maduixes tenen més vitamina C que les taronges."}},{"id":"lottery-death-odds-vs-winning","subject":"Lottery","text":{"en":"The chances of you dying on the way to get lottery tickets is higher than your chances of winning.","es":"Tienes más probabilidades de morir de camino a comprar un billete de lotería que de ganarla.","ca":"Tens més probabilitats de morir de camí a comprar un bitllet de loteria que de guanyar-la."}},{"id":"humans-only-animal-blush","subject":"Blushing","text":{"en":"Humans are the only animals that blush.","es":"Los humanos son los únicos animales que se sonrojan.","ca":"Els humans són els únics animals que s'enrojolen."}},{"id":"geese-gaggle-skein","subject":"Goose","text":{"en":"A group of geese on the ground is called a gaggle, but in flight, it's called a skein.","es":"A un grupo de gansos en tierra se le llama «gaggle», pero en pleno vuelo se le llama «skein».","ca":"A un grup d'oques a terra se l'anomena «gaggle», però quan volen se l'anomena «skein»."}},{"id":"jessica-name-shakespeare","subject":"The Merchant of Venice","text":{"en":"The name 'Jessica' was created by Shakespeare for his play Merchant of Venice.","es":"El nombre «Jessica» fue creado por Shakespeare para su obra El mercader de Venecia.","ca":"El nom «Jessica» va ser creat per Shakespeare per a la seva obra El mercader de Venècia."}},{"id":"tennis-originally-bare-hands","subject":"Real tennis","text":{"en":"Tennis was originally played with bare hands.","es":"El tenis se jugaba originalmente con las manos desnudas.","ca":"El tennis es jugava originalment amb les mans nues."}},{"id":"lemur-group-conspiracy","subject":"Lemur","text":{"en":"A group of lemurs is called a conspiracy.","es":"En inglés, a un grupo de lémures se le llama «conspiracy» (‘conspiración’).","ca":"En anglès, a un grup de lèmurs se l'anomena «conspiracy» («conspiració»)."}},{"id":"casu-marzu-cheese-maggots","subject":"Casu marzu","text":{"en":"Casu Marzu is a Sardinian cheese that contains live maggots and is considered a delicacy.","es":"El casu marzu es un queso sardo que contiene larvas vivas y se considera un manjar.","ca":"El casu marzu és un formatge sard que conté larves vives i es considera una delicatessen."}},{"id":"ants-weight-equals-humans","subject":"Ant","text":{"en":"All the ants on Earth weigh about as much as all the humans.","es":"Todas las hormigas de la Tierra pesan aproximadamente lo mismo que todos los humanos.","ca":"Totes les formigues de la Terra pesen aproximadament el mateix que tots els humans."}},{"id":"sneeze-speed-100mph","subject":"Sneeze","text":{"en":"A sneeze travels out of your mouth at over 100 miles per hour.","es":"Un estornudo sale de la boca a más de 100 millas por hora.","ca":"Un esternut surt de la boca a més de 100 milles per hora."}},{"id":"longest-english-word-189819-letters","subject":"Titin","text":{"en":"The longest English word is 189,819 letters long and would take three and a half hours to pronounce.","es":"La palabra más larga en inglés tiene 189 819 letras y tardaría tres horas y media en pronunciarse.","ca":"La paraula més llarga en anglès té 189.819 lletres i trigaria tres hores i mitja a pronunciar-se."}},{"id":"butterfly-group-kaleidoscope","subject":"Butterfly","text":{"en":"A group of butterflies is called a kaleidoscope.","es":"En inglés, a un grupo de mariposas se le llama «kaleidoscope» (‘calidoscopio’).","ca":"En anglès, a un grup de papallones se l'anomena «kaleidoscope» («calidoscopi»)."}},{"id":"electric-chair-invented-by-dentist","subject":"Alfred P. Southwick","text":{"en":"The electric chair was invented by a dentist.","es":"La silla eléctrica fue inventada por un dentista.","ca":"La cadira elèctrica va ser inventada per un dentista."}},{"id":"cannot-snore-and-dream-simultaneously","subject":"Snoring","text":{"en":"You cannot snore and dream at the same time.","es":"No se puede roncar y soñar al mismo tiempo.","ca":"No es pot roncar i somiar al mateix temps."}},{"id":"human-teeth-strong-as-shark-teeth","subject":"Tooth enamel","text":{"en":"Human teeth are just as strong as shark teeth.","es":"Los dientes humanos son tan resistentes como los de un tiburón.","ca":"Les dents humanes són tan resistents com les d'un tauró."}},{"id":"brain-uses-20-percent-oxygen-blood","subject":"Human brain","text":{"en":"Your brain uses 20% of the total oxygen and blood in your body.","es":"El cerebro utiliza el 20 % del oxígeno y la sangre total del cuerpo.","ca":"El cervell utilitza el 20 % de l'oxigen i la sang total del cos."}},{"id":"kangaroo-group-mob","subject":"Kangaroo","text":{"en":"A group of kangaroos is called a mob.","es":"En inglés, a un grupo de canguros se le llama «mob» (‘turba’).","ca":"En anglès, a un grup de cangurs se l'anomena «mob» («multitud»)."}},{"id":"humans-share-dna-with-bananas","subject":"Banana","text":{"en":"Humans share 50% of their DNA with bananas.","es":"Los humanos comparten el 50 % de su ADN con los plátanos.","ca":"Els humans comparteixen el 50 % del seu ADN amb els plàtans."}},{"id":"chicken-longest-flight-13-seconds","subject":"Chicken","text":{"en":"The longest recorded flight of a chicken is 13 seconds.","es":"El vuelo más largo registrado de una gallina duró 13 segundos.","ca":"El vol més llarg registrat d'una gallina va durar 13 segons."}},{"id":"cat-group-clowder","subject":"Cat","text":{"en":"A group of cats is called a clowder.","es":"En inglés, a un grupo de gatos se le llama «clowder».","ca":"En anglès, a un grup de gats se l'anomena «clowder»."}},{"id":"blue-whale-tongue-weighs-elephant","subject":"Blue whale","text":{"en":"A blue whale's tongue weighs as much as an elephant.","es":"La lengua de una ballena azul pesa tanto como un elefante.","ca":"La llengua d'una balena blava pesa tant com un elefant."}},{"id":"fall-to-center-of-earth-19-minutes","subject":"Earth","text":{"en":"It would take 19 minutes to fall to the center of the Earth.","es":"Se tardarían 19 minutos en caer hasta el centro de la Tierra.","ca":"Es trigarien 19 minuts a caure fins al centre de la Terra."}},{"id":"longest-place-name-85-letters","subject":"Taumatawhakatangihangakoauauotamateaturipukakapikimaungahoronukupokaiwhenuakitanatahu","text":{"en":"The longest place name on the planet is 85 letters long.","es":"El nombre de lugar más largo del planeta tiene 85 letras.","ca":"El nom de lloc més llarg del planeta té 85 lletres."}},{"id":"eagle-group-convocation","subject":"Eagle","text":{"en":"A group of eagles is called a convocation.","es":"En inglés, a un grupo de águilas se le llama «convocation» (‘convocatoria’).","ca":"En anglès, a un grup d'àguiles se l'anomena «convocation» («convocatòria»)."}},{"id":"impossible-to-lick-own-elbow","subject":"Elbow","text":{"en":"It is impossible for most people to lick their own elbow.","es":"A la mayoría de las personas les resulta imposible lamerse su propio codo.","ca":"A la majoria de les persones els resulta impossible llepar-se el propi colze."}},{"id":"girl-coined-phrase-the-internet-1996","subject":"Internet","text":{"en":"An 11-year-old girl invented the phrase 'the Internet' in 1996.","es":"Una niña de 11 años acuñó la expresión «the Internet» en 1996.","ca":"Una nena d'11 anys va encunyar l'expressió «the Internet» el 1996."}},{"id":"body-heat-boils-half-gallon-water","subject":"Human body temperature","text":{"en":"Your body gives off enough heat in 30 minutes to bring half a gallon of water to a boil.","es":"En 30 minutos, el cuerpo humano desprende suficiente calor como para hervir medio galón de agua.","ca":"En 30 minuts, el cos humà desprèn prou calor per bullir mig galó d'aigua."}},{"id":"average-person-passes-36-murderers","subject":"Murder","text":{"en":"The average person walks past 36 murderers in their lifetime.","es":"La persona promedio se cruza con 36 asesinos a lo largo de su vida.","ca":"La persona mitjana es creua amb 36 assassins al llarg de la seva vida."}},{"id":"oldest-chewing-gum-9000-years","subject":"Chewing gum","text":{"en":"The world's oldest piece of chewing gum is over 9,000 years old.","es":"El chicle más antiguo del mundo tiene más de 9000 años.","ca":"El xiclet més antic del món té més de 9.000 anys."}},{"id":"frog-group-army","subject":"Frog","text":{"en":"A group of frogs is called an army.","es":"En inglés, a un grupo de ranas se le llama «army» (‘ejército’).","ca":"En anglès, a un grup de granotes se l'anomena «army» («exèrcit»)."}},{"id":"microwave-inventor-received-2-dollars","subject":"Percy Spencer","text":{"en":"The inventor of the microwave only received $2 for his discovery.","es":"El inventor del microondas solo recibió 2 dólares por su descubrimiento.","ca":"L'inventor del microones només va rebre 2 dòlars pel seu descobriment."}},{"id":"eyes-same-size-nose-ears-keep-growing","subject":"Human eye","text":{"en":"Your eyes stay the same size from birth, but your nose and ears never stop growing.","es":"Los ojos mantienen el mismo tamaño desde el nacimiento, pero la nariz y las orejas nunca dejan de crecer.","ca":"Els ulls mantenen la mateixa mida des del naixement, però el nas i les orelles no deixen mai de créixer."}},{"id":"lobster-group-risk","subject":"Lobster","text":{"en":"A group of lobsters is called a risk.","es":"En inglés, a un grupo de langostas se le llama «risk» (‘riesgo’).","ca":"En anglès, a un grup de llagostes se l'anomena «risk» («risc»)."}},{"id":"cigarette-lighter-before-match","subject":"Lighter","text":{"en":"The cigarette lighter was invented before the match.","es":"El mechero fue inventado antes que la cerilla.","ca":"L'encenedor va ser inventat abans que el llumí."}},{"id":"goldfish-dark-room-turns-white","subject":"Goldfish","text":{"en":"If you keep a goldfish in a dark room, it will eventually turn white.","es":"Si mantienes a un pez dorado en una habitación oscura, con el tiempo se volverá blanco.","ca":"Si mantens un peix daurat en una habitació fosca, amb el temps es tornarà blanc."}},{"id":"dolphins-sleep-one-eye-open","subject":"Dolphin","text":{"en":"Dolphins sleep with one eye open.","es":"Los delfines duermen con un ojo abierto.","ca":"Els dofins dormen amb un ull obert."}},{"id":"giraffe-group-tower","subject":"Giraffe","text":{"en":"A group of giraffes is called a tower.","es":"En inglés, a un grupo de jirafas se le llama «tower» (‘torre’).","ca":"En anglès, a un grup de girafes se l'anomena «tower» («torre»)."}},{"id":"average-person-two-weeks-kissing","subject":"Kiss","text":{"en":"The average person spends two weeks of their life kissing.","es":"La persona promedio pasa dos semanas de su vida besando.","ca":"La persona mitjana passa dues setmanes de la seva vida besant."}},{"id":"seahorses-monogamous-for-life","subject":"Seahorse","text":{"en":"Sea horses are monogamous and mate for life.","es":"Los caballitos de mar son monógamos y se aparean de por vida.","ca":"Els cavallets de mar són monògams i s'aparellen de per vida."}},{"id":"hedgehog-group-prickle","subject":"Hedgehog","text":{"en":"A group of hedgehogs is called a prickle.","es":"En inglés, a un grupo de erizos se le llama «prickle» (‘pincho’).","ca":"En anglès, a un grup d'eriçons se l'anomena «prickle» («punxa»)."}},{"id":"russia-larger-than-pluto","subject":"Russia","text":{"en":"Russia has a larger surface area than Pluto.","es":"Rusia tiene una superficie mayor que la de Plutón.","ca":"Rússia té una superfície més gran que la de Plutó."}},{"id":"french-official-language-england-600-years","subject":"Anglo-Norman language","text":{"en":"French was the official language of England for over 600 years.","es":"El francés fue el idioma oficial de Inglaterra durante más de 600 años.","ca":"El francès va ser la llengua oficial d'Anglaterra durant més de 600 anys."}},{"id":"gorilla-group-band","subject":"Gorilla","text":{"en":"A group of gorillas is called a band.","es":"En inglés, a un grupo de gorilas se le llama «band» (‘banda’).","ca":"En anglès, a un grup de goril·les se l'anomena «band» («banda»)."}},{"id":"wood-frog-holds-pee-eight-months","subject":"Wood frog","text":{"en":"The wood frog can hold its pee for up to eight months.","es":"La rana de bosque puede retener la orina hasta ocho meses.","ca":"La granota de bosc pot retenir l'orina fins a vuit mesos."}},{"id":"antarctica-largest-desert","subject":"Antarctica","text":{"en":"Antarctica is the largest desert in the world.","es":"La Antártida es el desierto más grande del mundo.","ca":"L'Antàrtida és el desert més gran del món."}},{"id":"shark-group-shiver","subject":"Shark","text":{"en":"A group of sharks is called a shiver.","es":"En inglés, a un grupo de tiburones se le llama «shiver» (‘escalofrío’).","ca":"En anglès, a un grup de taurons se l'anomena «shiver» («esgarrifança»)."}},{"id":"vending-machines-kill-more-than-sharks","subject":"Vending machine","text":{"en":"More people are killed each year by vending machines than by sharks.","es":"Cada año mueren más personas a causa de las máquinas expendedoras que por ataques de tiburón.","ca":"Cada any moren més persones a causa de les màquines expenedores que per atacs de tauró."}},{"id":"squirrel-group-scurry","subject":"Squirrel","text":{"en":"A group of squirrels is called a scurry.","es":"En inglés, a un grupo de ardillas se le llama «scurry» (‘correteo’).","ca":"En anglès, a un grup d'esquirols se l'anomena «scurry» («corredissa»)."}},{"id":"longest-time-without-sleep-11-days","subject":"Randy Gardner (record holder)","text":{"en":"The longest anyone has ever gone without sleep is 11 days.","es":"El mayor tiempo que alguien ha estado sin dormir es de 11 días.","ca":"El major temps que algú ha estat sense dormir és d'11 dies."}},{"id":"ant-group-colony","subject":"Ant","text":{"en":"A group of ants is called a colony.","es":"A un grupo de hormigas se le llama colonia.","ca":"A un grup de formigues se l'anomena colònia."}},{"id":"pigs-cannot-look-up-at-sky","subject":"Pig","text":{"en":"Pigs cannot look up at the sky.","es":"Los cerdos no pueden mirar hacia el cielo.","ca":"Els porcs no poden mirar cap al cel."}},{"id":"roulette-numbers-sum-666","subject":"Roulette","text":{"en":"The sum of all the numbers on a roulette wheel is 666.","es":"La suma de todos los números de una ruleta es 666.","ca":"La suma de tots els números d'una ruleta és 666."}},{"id":"peacock-group-ostentation","subject":"Peafowl","text":{"en":"A group of peacocks is called an ostentation.","es":"En inglés, a un grupo de pavos reales se le llama «ostentation» (‘ostentación’).","ca":"En anglès, a un grup de paons se l'anomena «ostentation» («ostentació»)."}},{"id":"first-computer-virus-1983","subject":"Computer virus","text":{"en":"The first computer virus was created in 1983.","es":"El primer virus informático se creó en 1983.","ca":"El primer virus informàtic es va crear el 1983."}},{"id":"fox-group-skulk","subject":"Fox","text":{"en":"A group of foxes is called a skulk.","es":"En inglés, a un grupo de zorros se le llama «skulk».","ca":"En anglès, a un grup de guineus se l'anomena «skulk»."}},{"id":"physically-impossible-pigs-look-up","subject":"Pig","text":{"en":"It is physically impossible for pigs to look up into the sky.","es":"Es físicamente imposible que los cerdos miren hacia el cielo.","ca":"És físicament impossible que els porcs mirin cap al cel."}},{"id":"loudest-animal-sperm-whale","subject":"Sperm whale","text":{"en":"The loudest animal on Earth is the sperm whale.","es":"El animal más ruidoso de la Tierra es el cachalote.","ca":"L'animal més sorollós de la Terra és el catxalot."}},{"id":"toad-group-knot","subject":"Toad","text":{"en":"A group of toads is called a knot.","es":"En inglés, a un grupo de sapos se le llama «knot» (‘nudo’).","ca":"En anglès, a un grup de gripaus se l'anomena «knot» («nus»)."}},{"id":"baby-carrots-are-regular-carrots-cut","subject":"Baby carrot","text":{"en":"Baby carrots are just regular carrots cut and shaped into smaller pieces.","es":"Las zanahorias baby son simplemente zanahorias normales cortadas y talladas en trozos más pequeños.","ca":"Les pastanagues baby són simplement pastanagues normals tallades i modelades en trossos més petits."}},{"id":"google-original-name-backrub","subject":"BackRub","text":{"en":"The original name for the search engine Google was Backrub.","es":"El nombre original del buscador Google era Backrub.","ca":"El nom original del cercador Google era Backrub."}},{"id":"wolf-group-pack","subject":"Wolf","text":{"en":"A group of wolves is called a pack.","es":"A un grupo de lobos se le llama manada.","ca":"A un grup de llops se l'anomena manada."}},{"id":"water-pouring-sounds-temperature","subject":"Water","text":{"en":"Water makes different pouring sounds depending on its temperature.","es":"El agua produce sonidos distintos al verterse según su temperatura.","ca":"L'aigua produeix sons diferents en abocar-se segons la seva temperatura."}},{"id":"most-expensive-pizza-12000-dollars","subject":"Pizza","text":{"en":"The most expensive pizza in the world costs $12,000 and takes 72 hours to make.","es":"La pizza más cara del mundo cuesta 12 000 dólares y tarda 72 horas en prepararse.","ca":"La pizza més cara del món costa 12.000 dòlars i triga 72 hores a preparar-se."}},{"id":"snake-group-den","subject":"Snake","text":{"en":"A group of snakes is called a den.","es":"En inglés, a un grupo de serpientes se le llama «den» (‘guarida’).","ca":"En anglès, a un grup de serps se l'anomena «den» («cau»)."}},{"id":"humans-only-animal-cry-emotional-tears","subject":"Tears","text":{"en":"Humans are the only animals that cry emotional tears.","es":"Los humanos son los únicos animales que lloran lágrimas emocionales.","ca":"Els humans són els únics animals que ploren llàgrimes emocionals."}}];
